template.solver:
def solve(n):
    S = set(x for x in range(10, 100) if x % 17 == 0 or x % 43 == 0)
    cnt = [1] * 10
    for _ in range(n - 1):
        new = [0] * 10
        for a in range(10):
            new[a] = sum(cnt[b] for b in range(10) if 10 * a + b in S)
        cnt = new
    return sum(cnt[1:10])
